"""Temporary validation harness; only patches this test module's probe clock."""
import sys
from datetime import datetime, timezone

import pytest


class ClockPlugin:
    @pytest.fixture(autouse=True)
    def outer_probe_clock(self, monkeypatch, request):
        if DISABLE_PIN:
            monkeypatch.setattr(request.module, "pin_probe_clock", lambda monkeypatch: None)
        if CLOCK == "real":
            return
        instant = datetime.fromisoformat(CLOCK.replace("Z", "+00:00"))

        class OuterClock(datetime):
            @classmethod
            def now(cls, tz=None):
                return instant.astimezone(tz) if tz else instant.replace(tzinfo=None)

        monkeypatch.setattr(request.module.probe, "datetime", OuterClock)


CLOCK = sys.argv[1]
DISABLE_PIN = "--disable-pin" in sys.argv
if DISABLE_PIN:
    sys.argv.remove("--disable-pin")
raise SystemExit(pytest.main([
    "-q", "--tb=line", "--show-capture=no",
    "acceptance/test_paper_risk_policy_binding.py", *sys.argv[2:]
], plugins=[ClockPlugin()]))
